def longest_palindrome_subseq(s):
    def f(i, j):               # best palindrome inside s[i..j]
        if i > j:
            return 0
        if i == j:
            return 1
        if s[i] == s[j]:
            return 2 + f(i + 1, j - 1)
        return max(f(i + 1, j), f(i, j - 1))
    return f(0, len(s) - 1)

