def longest_palindrome_subseq(s):
    n = len(s)
    dp = [[0] * n for _ in range(n)]
    for i in range(n - 1, -1, -1):
        dp[i][i] = 1
        for j in range(i + 1, n):
            if s[i] == s[j]:
                dp[i][j] = 2 + dp[i + 1][j - 1]
            else:
                dp[i][j] = max(dp[i + 1][j], dp[i][j - 1])
    return dp[0][n - 1]

def longest_palindrome_subseq(s):
    n = len(s)
    below = [0] * n            # row i+1
    for i in range(n - 1, -1, -1):
        cur = [0] * n
        cur[i] = 1
        for j in range(i + 1, n):
            if s[i] == s[j]:
                cur[j] = 2 + below[j - 1]
            else:
                cur[j] = max(below[j], cur[j - 1])
        below = cur
    return below[n - 1]

def longest_palindrome_subseq(s):
    r = s[::-1]
    row = [0] * (len(r) + 1)
    for ch in s:
        diag = 0
        for j in range(1, len(r) + 1):
            above = row[j]
            row[j] = diag + 1 if ch == r[j - 1] else max(above, row[j - 1])
            diag = above
    return row[-1]
